sp_ListarCategoriaProduto	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarCategoriaProduto`(IN p_idEmpresa INT)\nBEGIN\n\n    SELECT c.idCategoriaProduto AS idCategoria,\n\n           1                    AS idEmpresa,\n\n           c.Nome               AS nome,\n\n           c.Descricao          AS descricao,\n\n           c.categoria_pai_id   AS idCategoriaPai,\n\n           p.Nome               AS nomeCategoriaPai,\n\n           c.fAtivo\n\n    FROM CategoriaProduto c\n\n    LEFT JOIN CategoriaProduto p ON p.idCategoriaProduto = c.categoria_pai_id\n\n    ORDER BY c.Nome;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
